const $=id=>document.getElementById(id);
function parseAmount(s){s=s.trim().replace(/\$/g,'').replace(/\s/g,'');if(!s)return 0;if(!/^\d+(?:[.,]\d+)*$/.test(s))return NaN;if(s.includes(',')){if((s.match(/,/g)||[]).length>1)return NaN;s=s.replace(/\./g,'').replace(',','.')}else if(/^\d{1,3}(\.\d{3})+$/.test(s)){s=s.replace(/\./g,'')}else if((s.match(/\./g)||[]).length>1)return NaN;return Number(s)}
function calculate(total,rate){const gross=Math.round(total*100);const discount=Math.round(gross*rate/100);return {gross:gross/100,discount:discount/100,net:(gross-discount)/100}}
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',minimumFractionDigits:2}).format(n);let mode='total',last=null;
function update(){const a=mode==='total'?parseAmount($('total').value):parseAmount($('employee').value)+parseAmount($('employer').value);const rate=parseAmount($('rate').value);const invalid=!Number.isFinite(a)||!Number.isFinite(rate)||rate<0||rate>100||a>1e12;$('error').hidden=!invalid;$('error').textContent='Ingresá importes válidos y un descuento entre 0 y 100%. Ejemplo: 128.926,41.';$('copy').disabled=invalid;$('result-panel').hidden=invalid||a<=0;last=invalid?null:{...calculate(a,rate),rate};$('net').textContent=last?money(last.net):'—';$('gross').textContent=last?money(last.gross):'—';$('discount').textContent=last?money(last.discount):'—';$('discount-label').textContent=`Descuento (${Number.isFinite(rate)?rate.toLocaleString('es-AR'):'—'}%)`;window.dispatchEvent(new Event('aportes-updated'))}
function setMode(m){mode=m;const t=m==='total';$('total-pane').hidden=!t;$('detail-pane').hidden=t;$('tab-total').setAttribute('aria-selected',String(t));$('tab-detail').setAttribute('aria-selected',String(!t));update()}
$('tab-total').onclick=()=>setMode('total');$('tab-detail').onclick=()=>setMode('detail');document.querySelectorAll('#settings input:not([type=file])').forEach(x=>x.addEventListener('input',()=>{$('status').textContent='';update()}));$('example').onclick=()=>{$('total').value='128.926,41';$('employee').value='42.975,47';$('employer').value='85.950,94';$('rate').value='15';update()};$('clear').onclick=()=>{if(ocrBusy)return;$('photo').value='';$('photo-preview').hidden=true;$('photo-tools').hidden=true;window.resetReceiptPhoto?.();$('ocr-details').hidden=true;$('ocr-status').textContent='';$('candidates').replaceChildren();['total','employee','employer'].forEach(id=>$(id).value='');$('rate').value='15';$('status').textContent='';update()};$('copy').onclick=async()=>{if(!last)return;const text=`Aportes de obra social\nTotal: ${money(last.gross)}\nDescuento (${last.rate}%): ${money(last.discount)}\nImporte estimado disponible: ${money(last.net)}\nMonto sujeto a confirmación por Fesalud.`;try{await navigator.clipboard.writeText(text);$('status').textContent='Resultado copiado. Podés pegarlo en WhatsApp.'}catch{$('status').textContent='No se pudo copiar automáticamente. Seleccioná y copiá el importe.'}};update();
let ocrBusy=false;
function receiptCanvas(img,region){const [x,y,w,h]=region;const canvas=document.createElement('canvas');const sourceWidth=img.naturalWidth*w,sourceHeight=img.naturalHeight*h;const scale=Math.min(5,1800/sourceWidth);canvas.width=Math.round(sourceWidth*scale);canvas.height=Math.round(sourceHeight*scale);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,img.naturalWidth*x,img.naturalHeight*y,sourceWidth,sourceHeight,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),hist=new Uint32Array(256);for(let i=0;i<pixels.data.length;i+=4){const g=Math.round(.299*pixels.data[i]+.587*pixels.data[i+1]+.114*pixels.data[i+2]);pixels.data[i]=g;hist[g]++}const count=canvas.width*canvas.height;let low=0,high=255,sum=0;for(let i=0;i<256;i++){sum+=hist[i];if(sum>=count*.01){low=i;break}}sum=0;for(let i=255;i>=0;i--){sum+=hist[i];if(sum>=count*.01){high=i;break}}for(let i=0;i<pixels.data.length;i+=4){const g=Math.max(0,Math.min(255,Math.round((pixels.data[i]-low)*255/Math.max(1,high-low))));pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=g}ctx.putImageData(pixels,0,0);return canvas}
function showCandidates(options){
 const candidatesByKey=new Map();for(const option of options){const key=option.kind+':'+option.amount.toFixed(2),previous=candidatesByKey.get(key);if(!previous||option.verified)candidatesByKey.set(key,option)}
 const totals=[...candidatesByKey.values()].filter(o=>o.isTotal),verified=totals.filter(o=>o.verified);
 const selected=verified.length===1?verified[0]:null;
 if(selected){$('total').value=selected.amount.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});setMode('total');$('settings').open=false;$('ocr-status').textContent='Listo. Total comprobado con trabajador + empleador.';$('status').textContent='Revisá que el total de obra social coincida con el recibo.';$('result-panel').scrollIntoView({behavior:'smooth',block:'nearest'})}
 else{$('total').value='';$('employee').value='';$('employer').value='';update();$('result-panel').hidden=true;$('ocr-status').textContent='No pude comprobar los tres importes de obra social. Sacá una foto más cercana del detalle donde dice Total, Empleador y Trabajador, o cargalos en Ajustes.';$('status').textContent=''}
}
async function readPhoto(file){if(!file||ocrBusy)return;if(file.size>25*1024*1024){$('ocr-status').textContent='La foto supera 25 MB. Elegí una imagen más pequeña.';return}ocrBusy=true;$('status').textContent='';const input=$('photo');input.disabled=true;$('clear').disabled=true;$('candidates').replaceChildren();$('ocr-details').hidden=true;['total','employee','employer'].forEach(id=>$(id).value='');update();let worker,url;try{url=URL.createObjectURL(file);const img=$('photo-preview');img.src=url;img.hidden=false;await img.decode();$('photo-tools').hidden=false;window.rememberReceiptPhoto?.(file);$('ocr-status').textContent='Preparando lector. La primera lectura puede demorar…';let pass=0;worker=await Tesseract.createWorker('spa',1,{workerPath:new URL('ocr/worker.min.js',location.href).href,corePath:new URL('ocr/',location.href).href,langPath:new URL('ocr',location.href).href,logger:m=>{if(m.status==='recognizing text')$('ocr-status').textContent=`Leyendo sector ${pass}/3… ${Math.round(m.progress*100)}%`}});const regions=[[0,0,1,1],[0,.6,.48,.18],[0,.75,.48,.23]],texts=[],all=[];for(let i=0;i<regions.length;i++){pass=i+1;await worker.setParameters({tessedit_pageseg_mode:i===0?'11':'6'});const canvas=receiptCanvas(img,regions[i]);const {data}=await worker.recognize(canvas);texts.push(`SECTOR ${i+1}\n${data.text}`);all.push(...extractCandidates(data.text),...extractSpatialCandidates(data,canvas.width))} $('ocr-text').textContent=texts.join('\n\n');$('ocr-details').hidden=false;showCandidates(all)}catch(err){$('ocr-status').textContent='No se pudo leer esta imagen. Probá con JPG o PNG, buena luz y el recibo derecho. También podés cargar los importes manualmente.'}finally{try{if(worker)await worker.terminate()}finally{ocrBusy=false;input.disabled=false;$('clear').disabled=false;if(url)URL.revokeObjectURL(url)}}}
$('photo').addEventListener('change',e=>readPhoto(e.target.files[0]));
